// Generates src/data/programs.ts, src/data/icons.ts and src/data/ui.ts from herdr-app's program table and
// icons (Apache-2.0, see NOTICE). Run: node scripts/gen-assets.mjs
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const table = JSON.parse(readFileSync(join(root, 'src/data/programs.json'), 'utf8'))
writeFileSync(join(root, 'src/data/programs.ts'),
  '// Generated by scripts/gen-assets.mjs from herdr-app defaults/programs.json. Do not edit.\n' +
  `export const PROGRAMS: { shells: string[]; interpreters: string[]; programs: Record<string, { name?: string; icon?: string; tint?: boolean; tile?: string; color?: string; match?: string[]; run?: string[] }> } = ${JSON.stringify(table, null, 1)}\n`)

const ident = (f) => 'i_' + f.replace(/\.svg$/, '').replace(/[^A-Za-z0-9]/g, '_')
function gen(dir, name, out) {
  const files = readdirSync(join(root, dir)).filter((f) => f.endsWith('.svg')).sort()
  writeFileSync(join(root, out),
    '// Generated by scripts/gen-assets.mjs. Do not edit.\n' +
    files.map((f) => `import ${ident(f)} from '../../${dir}/${f}'`).join('\n') +
    `\n\nexport const ${name}: Record<string, any> = {\n` +
    files.map((f) => `  ${JSON.stringify(f.replace(/\.svg$/, ''))}: ${ident(f)},`).join('\n') + '\n}\n')
}
gen('assets/icons', 'PROGRAM_ICONS', 'src/data/icons.ts')
gen('assets/ui', 'UI', 'src/data/ui.ts')
